package com.evanescent.mytasks.di

import android.content.Context
import com.evanescent.mytasks.data.db.AppDatabase
import com.evanescent.mytasks.data.db.TaskDao
import dagger.Module
import dagger.Provides
import dagger.hilt.InstallIn
import dagger.hilt.android.qualifiers.ApplicationContext
import dagger.hilt.components.SingletonComponent
import javax.inject.Singleton

@Module
@InstallIn(SingletonComponent::class)
object DataModule {

    @Provides
    @Singleton
    fun provideAppDatabase(@ApplicationContext context: Context): AppDatabase {
        return AppDatabase.getDatabase(context)
    }

    @Provides
    fun provideTaskDao(appDatabase: AppDatabase): TaskDao {
        return appDatabase.taskDao()
    }

    @Provides
    @Singleton
    fun provideTasksRepository(@ApplicationContext context: Context): com.evanescent.mytasks.data.repository.TasksRepository {
        return com.evanescent.mytasks.data.repository.TasksRepository(context)
    }
}

