    private fun showLanguagePopup(anchor: View) {
        val popup = PopupMenu(this, anchor)
        popup.menu.add(Menu.NONE, 1, Menu.NONE, "English")
        popup.menu.add(Menu.NONE, 2, Menu.NONE, "Français")

        popup.setOnMenuItemClickListener { item ->
            when (item.itemId) {
                1 -> {
                    setLocale("en")
                    true
                }
                2 -> {
                    setLocale("fr")
                    true
                }
                else -> false
            }
        }
        popup.show()
    }

    private fun setLocale(lang: String) {
        val appLocale: LocaleListCompat = LocaleListCompat.forLanguageTags(lang)
        AppCompatDelegate.setApplicationLocales(appLocale)
    }

    override fun onOptionsItemSelected(item: MenuItem): Boolean {
        return when (item.itemId) {
            R.id.action_settings -> {
                // Handle settings action, e.g., startActivity(Intent(this, SettingsActivity::class.java))
                true
            }
            else -> super.onOptionsItemSelected(item)
        }
    }

